prompt:
Two definitions in two units.
1. Add `abs_diff` to the existing unit `num`: for a and b with |a|, |b| <= 1000000000 (as `num::small` states), return |a - b|. Its contract must state that the result is >= 0 and equals a - b or b - a.
2. Create unit `tasks` and implement `max_gap` using `num::abs_diff`: for an array whose elements all lie in [-1000, 1000], return the largest absolute difference between neighbours (0 if there are fewer than two elements). Its contract must state that the result is >= 0 and that no neighbour difference exceeds it in either direction.

Required signatures:
fn abs_diff(a: i64, b: i64) -> (r: i64)   (in unit `num`)
fn max_gap(a: &[i64]) -> (r: i64)   (in unit `tasks`)

reference.code:
spec fn is_dist(a: i64, b: i64, r: i64) -> bool { r >= 0 && (r == a - b || r == b - a) }

#[effects(pure)]
#[uses(small, is_dist)]
fn abs_diff(a: i64, b: i64) -> (r: i64)
    requires small(a), small(b),
    ensures is_dist(a, b, r),
{
    if a >= b {
        a - b
    } else {
        b - a
    }
}

spec fn elems_ok(a: &[i64]) -> bool { forall|k: usize| k < a.len() ==> -1000 <= #[trigger] a[k] && a[k] <= 1000 }

spec fn gap_below(a: &[i64], n: usize, g: i64) -> bool { forall|k: usize| k + 1 < n ==> a[k + 1] - #[trigger] a[k] <= g && a[k] - a[k + 1] <= g }

spec fn gap_ok(a: &[i64], g: i64) -> bool { 0 <= g && (forall|k: usize| k + 1 < a.len() ==> a[k + 1] - #[trigger] a[k] <= g && a[k] - a[k + 1] <= g) }

#[effects(pure)]
#[uses(elems_ok, gap_below, gap_ok, num::small, num::is_dist)]
fn max_gap(a: &[i64]) -> (r: i64)
    requires elems_ok(a),
    ensures gap_ok(a, r),
{
    let mut g: i64 = 0;
    let mut k: usize = 1;
    while k < a.len()
        invariant 1 <= k, k <= a.len() || k == 1, 0 <= g, gap_below(a, k, g),
        decreases a.len() - k,
    {
        let d: i64 = num::abs_diff(a[k], a[k - 1]);
        if d > g {
            g = d;
        }
        k = k + 1;
    }
    g
}

