    if a >= b {
        a - b
    } else {
        b - a
    }
}

spec fn elems_ok(a: &[i64]) -> bool { forall|k: usize| k < a.len() ==> -1000 <= #[trigger] a[k] && a[k] <= 1000 }

spec fn gap_nonneg(g: i64) -> bool { 0 <= g }

#[effects(pure)]
#[uses(elems_ok, gap_nonneg, num::small, num::dist_nonneg)]
fn max_gap(a: &[i64]) -> (r: i64)
    requires elems_ok(a),
    ensures gap_nonneg(r),
{
    let mut g: i64 = 0;
    let mut k: usize = 1;
    while k < a.len()
        invariant 1 <= k, 0 <= g,
        decreases a.len() - k,
    {
        let d: i64 = num::abs_diff(a[k], a[k - 1]);
        if d > g {
            g = d;
        }
        k = k + 1;
    }
